import React, { useRef } from 'react';
import { WelcomeScreen } from './WelcomeScreen';
import { ChatArea } from './ChatArea';
import { InputArea } from './InputArea';

export const IntervieweeView = ({
  chatMessages,
  currentInput,
  setCurrentInput,
  handleSendMessage,
  handleFileUpload,
  uploadedFile,
  interviewStarted,
  timeRemaining,
  error,
  currentCandidate,
  chatEndRef,
  isUploading
}) => {
  const fileInputRef = useRef(null);

  // Show WelcomeScreen when there are no messages AND no file uploaded
  const showWelcomeScreen = chatMessages.length === 0 && !uploadedFile && !currentCandidate;

  return (
    <div className="mt-8"> {/* ✅ ADDED THIS WRAPPER WITH mt-8 */}
      <div className="bg-white rounded-2xl shadow-xl overflow-hidden">
        {/* Header - Only show when NOT on welcome screen */}
        {!showWelcomeScreen && (
          <div className="bg-gradient-to-r from-indigo-600 to-purple-600 px-6 py-4">
            <h2 className="text-xl font-bold text-white">Interview Session</h2>
            <p className="text-indigo-100 text-sm">
              {!uploadedFile
                ? 'Upload your resume to begin'
                : interviewStarted
                ? 'Answer the questions to complete your interview'
                : 'Ready to start your interview'}
            </p>
            {/* Timer Display - Show in header when interview started */}
            {interviewStarted && timeRemaining !== null && (
              <div className="mt-2 flex items-center gap-2 bg-white/20 backdrop-blur-sm rounded-lg px-4 py-2">
                <span className="text-white text-sm font-medium">⏱️ Time Remaining:</span>
                <span className={`text-lg font-bold ${
                  timeRemaining < 30 ? 'text-red-300' : 'text-white'
                }`}>
                  {Math.floor(timeRemaining / 60)}:{(timeRemaining % 60).toString().padStart(2, '0')}
                </span>
              </div>
            )}
          </div>
        )}

        {/* Main Content Area */}
        <div className={showWelcomeScreen ? 'h-[600px]' : 'h-[600px] flex flex-col overflow-hidden'}>
          {showWelcomeScreen ? (
            <WelcomeScreen
              onFileUpload={handleFileUpload}
              fileInputRef={fileInputRef}
            />
          ) : (
            <>
              {/* Error Display */}
              {error && (
                <div className="mx-6 mt-4 p-4 bg-red-50 border border-red-200 rounded-lg text-red-700 text-sm">
                  ⚠️ {error}
                </div>
              )}

              {/* Chat Area */}
              <ChatArea
                messages={chatMessages}
                chatEndRef={chatEndRef}
                isUploading={isUploading}
              />

              {/* Input Area */}
              <InputArea
                currentInput={currentInput}
                setCurrentInput={setCurrentInput}
                onSendMessage={handleSendMessage}
                onFileUpload={handleFileUpload}
                fileInputRef={fileInputRef}
                uploadedFile={uploadedFile}
                interviewStarted={interviewStarted}
                timeRemaining={timeRemaining}
                error={error}
                currentCandidate={currentCandidate}
                isCompleted={currentCandidate?.completed}
              />
            </>
          )}
        </div>
      </div>
    </div>
  );
};
